		time = '04:00't; *if not a trading day, and we have to go forward, start at 4AM next day;
		date = INTNX("DAY",date,1);
	end;
	if date > '31Dec2020'd then do;
		put "Error: Date out of Range";
		stop;
	end;
end;

*now that we have a valid date, find a valid minute;
rc=1;
do until(rc=0);
	if hexcd=3 then rc=nasd_d.find();
	else rc=nyse_d.find();
	*if the time does not fall on a trading minute, go to next minute;
	if rc ^= 0 then do;
		time = INTNX("minute",time,1,'b');
	end;
	if time > '21:00't then do;
		*if nothing then go to next day;
		time = '04:00't; *if not a trading day, and we have to go forward, start at 4AM next day;
		date = INTNX("DAY",date,1);
		go to datefind;
	end;
end;

*ok now that we have a valid event time we need to need to find the pre and post price;
*save the event time;
evt_time=time;
evt_date=date;
evt_dtm = dhms(date,0,0,time);
evt_min= min;


act_tmin_delay = act_evtmin - evt_min;
