*BELOW TAKES ABOUT 7 HRS TO RUN!;
*collect hourly returns and volume for trading days [t through t+5], where a day is defined as 16 trading hours; 
proc sort data=bjar.taq_evt_sample; by symbol evt_date evt_time; run;
%PUT %SYSFUNC(datetime(),datetime18.);
options nonotes nomprint msglevel=N;
DATA bjar.ts_taq (drop = mystring price rc idx);
format date begin_date yymmddn8. symbol $10. time begin_time evt_time evttims1 - evttims96 TIME8.;
set bjar.taq_evt_sample;
by symbol;

	*initialize variables for hash key and output data;
	min=.;
	price =.;
	total_value=.;
	total_shares=.;
	date = .;

DATA bjar.wmrt;
SET bjar.ts_taq;

array evtrets {96} evtrets1 - evtrets96;
array bhar {96} bhar1 - bhar96;
array pbhar {96} pbhar1 - pbhar96;
array wpbhar {96} wpbhar1 - wpbhar96;
array evttims {96} evttims1 - evttims96;
array shares {96} shares1 - shares96;
array value {96} value1 - value96;


sumret = 0;
sumvalue = 0;
*Cycle through the time windows;
DO I=1 to 96;

	sumret =sumret + evtrets(I);
	sumvalue = sumvalue + value(I);
	BHAR(I) = exp(sumret)-1;
	if bhar_0day ne 0 then PBHAR(I) = BHAR(I)/bhar_0day;
		else pbhar(I) = 0;
	if PBHAR(I) < - 1 then WPBHAR(I) = -1;
		else if PBHAR(I) > 1 then WPBHAR(I) = 1;
			else WPBHAR(I) = PBHAR(I);
end;

if sumvalue = 0 then delete; 
WMRT = sum(wpbhar4,wpbhar8,wpbhar12) + 0.5;

run;


*eliminate multiple matches per permno;
*keep the one with the highest total dollar volume in the window;
proc sort data = bjar.wmrt; by permno pends descending sumvalue; run;
proc sort data = bjar.wmrt nodupkey; by permno pends; run;

